$('#browse-who-not-btn').addEventListener('click', () => openCompanyBrowser('exclude'));
if ($('#browse-tuning-co-btn')) $('#browse-tuning-co-btn').addEventListener('click', () => openCompanyBrowser('exclude', 'tuning'));

